import os,stat,json,signal
from datetime import datetime,timezone
out={'captured_utc':datetime.now(timezone.utc).isoformat(),'kernel':os.uname().release,'scope':'fixed tracepoint id file metadata only; no id value read or event enabled','tracepoint':{'path':'/sys/kernel/tracing/events/sched/sched_process_fork/id','value_read':False}}
def timeout(*args):raise TimeoutError('metadata deadline')
signal.signal(signal.SIGALRM,timeout);signal.setitimer(signal.ITIMER_REAL,1)
try:
 s=os.stat(out['tracepoint']['path'])
 out['tracepoint'].update(exists=True,regular=stat.S_ISREG(s.st_mode),mode=oct(stat.S_IMODE(s.st_mode)),status='observed')
except FileNotFoundError:out['tracepoint'].update(exists=False,status='absent')
except Exception as e:out['tracepoint'].update(exists=None,status='unavailable',error_type=type(e).__name__,errno=getattr(e,'errno',None))
finally:signal.setitimer(signal.ITIMER_REAL,0)
out['actions']={'bpf_program_loaded':False,'bpf_map_created':False,'perf_event_open_called':False,'probe_attached':False,'trace_instance_created':False,'tracepoint_enabled':False,'fork_child_created':False,'kernel_memory_read':False,'module_loaded':False,'settings_changed':False,'radio_restart_or_qmi_call':False}
print(json.dumps(out))
